out<-"analysis/gamewell_secondary_ls_2026-10-16";res<-read.csv(file.path(out,"RESULTS.csv"),stringsAsFactors=FALSE);fx<-read.csv(file.path(out,"FIXED_EFFECTS.csv"),stringsAsFactors=FALSE);cr<-read.csv(file.path(out,"CR2_FIXED_EFFECTS.csv"),stringsAsFactors=FALSE);status<-read.csv(file.path(out,"FIT_STATUS.csv"),stringsAsFactors=FALSE);diag<-read.csv(file.path(out,"FIT1_RESIDUAL_SUMMARY.csv"),stringsAsFactors=FALSE);bins<-read.csv(file.path(out,"FIT1_RESIDUALS_BY_FITTED_BINS.csv"),stringsAsFactors=FALSE);gate<-read.csv(file.path(out,"PREFIT_COHORT_GATE.csv"),stringsAsFactors=FALSE)
ci_text<-function(lo,hi)sprintf("[%.6f, %.6f]",lo,hi)
lines<-c("# GameWell secondary analysis: life satisfaction","","## Gate","", "All seven SHA-256 checks passed for Plan v1, Addenda 1–5, and the interval dataset. The valence primary cohort reproduced 5,076 intervals, 371 participants, and 171 participants with exposure variation. Linked intervals with life satisfaction present at both endpoints before the 48-hour filter numbered 5,769. After applying the filter, the cohort contained 5,070 intervals and 371 participants, with 171 participants showing exposure variation. After filtering, 94 intervals had prior life satisfaction equal to zero, 95 had later life satisfaction equal to zero, and 128 had zero at either endpoint.","","## Models and results","","Life satisfaction is the distinct construct “satisfaction with my life today.” It was not merged with affective valence. Exactly two models were fitted, each once with REML and the default optimizer. Fit 1 uses the full eligible cohort; Fit 2 excludes intervals with zero at either life-satisfaction endpoint. Estimates describe associations with recorded linked-console play, not causal effects.","","### Exposure-within results","","Fit | N intervals / participants | Estimate per hour | Model 95% CI | CR2 SE (df) | CR2 95% CI | Wider CI | Estimate per 1 SD exposure | Estimate per within-person LS SD | Category | Singular","---|---:|---:|---|---:|---|---|---:|---:|:---:|:---|")
for(i in seq_len(nrow(res))){r<-res[i,];lines<-c(lines,sprintf("%s | %d / %d | %.6f | %s | %.6f (%.3f) | %s | %s %s | %.6f | %.6f | %s | %s",r$fit_id,r$n_intervals,r$n_participants,r$estimate_exposure_within,ci_text(r$model_CI_lower,r$model_CI_upper),r$CR2_SE,r$CR2_df,ci_text(r$CR2_CI_lower,r$CR2_CI_upper),r$wider_source,ci_text(r$wider_CI_lower,r$wider_CI_upper),r$estimate_per_1SD_exposure,r$estimate_per_within_person_LS_SD,r$category,as.character(r$singular_fit)))}
lines<-c(lines,"","Both wider intervals are entirely within +/-0.5 points per hour; by Addendum 2 item 3(a), category (a): “no association larger than the SESOI is supported.” No life-satisfaction power simulation was run.","","### Full model-based fixed effects","","Fit | Term | Estimate | SE | Satterthwaite df | t | p | Model 95% CI","---|---|---:|---:|---:|---:|---:|---|")
for(i in seq_len(nrow(fx))){r<-fx[i,];lines<-c(lines,sprintf("%s | %s | %.6f | %.6f | %.3f | %.4f | %.4g | %s",r$fit_id,r$term,r$estimate,r$SE,r$Satterthwaite_df,r$t,r$p,ci_text(r$CI_lower,r$CI_upper)))}
lines<-c(lines,"","### CR2 fixed effects","","CR2 results with Satterthwaite-type degrees of freedom are saved for all fixed effects in CR2_FIXED_EFFECTS.csv. The exposure_between term is conditional on prior_between, which closely tracks participant mean later outcome; it is not an unadjusted between-person association and is not confirmatory.","","## Fit status and diagnostics","",sprintf("Fit 1: convergence code %s; messages: %s; singular=%s; random-intercept SD=%.6f; residual SD=%.6f; ICC=%.6f.",status$convergence_code[1],status$convergence_messages[1],status$singular_fit[1],status$random_intercept_SD[1],status$residual_SD[1],status$ICC[1]),sprintf("Fit 2: convergence code %s; messages: %s; singular=%s; random-intercept SD=%.6f; residual SD=%.6f; ICC=%.6f.",status$convergence_code[2],status$convergence_messages[2],status$singular_fit[2],status$random_intercept_SD[2],status$residual_SD[2],status$ICC[2]),sprintf("Fit 1 residuals (n=%d): mean %.4f, SD %.4f, skewness %.4f, excess kurtosis %.4f; quantiles at 1/5/25/50/75/95/99%% were %.3f / %.3f / %.3f / %.3f / %.3f / %.3f / %.3f.",diag$n,diag$mean,diag$SD,diag$skewness,diag$excess_kurtosis,diag$q01,diag$q05,diag$q25,diag$median,diag$q75,diag$q95,diag$q99),sprintf("Across fitted-value deciles, residual SD ranged from %.3f to %.3f; the highest fitted decile had mean fitted %.3f and residual SD %.3f.",min(bins$residual_SD),max(bins$residual_SD),bins$mean_fitted[10],bins$residual_SD[10]),"Residual summary and bins are in FIT1_RESIDUAL_SUMMARY.csv and FIT1_RESIDUALS_BY_FITTED_BINS.csv. Histogram, QQ plot and residuals-by-fitted plot are SVG files. Diagnostics loaded Fit 1's saved model object and did not refit.","","## Limitations","","- Linked-platform coverage is subject to the existing coverage assumption; interval-level missing capture cannot be distinguished from genuine no-play.","- Nintendo telemetry covers first-party titles only; the recorded exposure is not total gaming.","- Both life-satisfaction fits are singular, with zero estimated random-intercept variance. Residual spread is lower at the top fitted-value decile, consistent with ceiling compression and heterogeneous variance.","- The data are observational, so estimates are associational and do not establish causal effects.","- Life satisfaction is a separate daily satisfaction construct and remains distinct from affective valence. Zero values are retained in Fit 1 and excluded only in Fit 2 as prespecified.","","## Execution record","","R was run using the specified executable with --vanilla. The two prespecified life-satisfaction models were each fitted once; no valence model was refitted. Fit 1 diagnostics used only the saved RDS. No participant IDs or data rows were printed or written to output. No packages were installed.")
writeLines(lines,file.path(out,"REPORT.md"),useBytes=TRUE);cat("Aggregate report written.\n")